  "title": "Contractions with em",
  "rule": "In Portuguese, 'em' combines with 'o' and 'a': use 'no' and 'na', not 'em o' or 'em a'. The same pattern applies to plural forms, 'nos' and 'nas'.",
  "contrast": [
    {
      "label": "'em' + 'o' becomes",
      "example": "no sofá"
    },
    {
      "label": "'em' + 'a' becomes",
      "example": "na escola"
    },
    {
      "label": "'em' + plural articles becomes",
      "example": "nos parques, nas lojas"
    }
  ],
  "drill": [
    {
      "sentence": "O cachorro dorme ___ sofá.",
      "answer": "no",
      "options": [
        "em o",
        "no"
      ],
      "feedback": "Use 'no' because 'em' combines with 'o'."
    },
    {
      "sentence": "A mochila está ___ cadeira.",
      "answer": "na",
      "options": [
        "em a",
        "na"
      ],
      "feedback": "Use 'na' because 'em' combines with 'a'."
    },
    {
      "sentence": "O jantar está ___ forno.",
      "answer": "no",
      "options": [
        "em o",
        "no"
      ],
      "feedback": "Use 'no' because 'em' combines with 'o'."
    },
    {
      "sentence": "As crianças brincam ___ parques.",
      "answer": "nos",
      "options": [
        "em os",
        "nos"
      ],
      "feedback": "Use 'nos' because 'em' combines with the plural 'os'."
    },
    {
      "sentence": "As chaves estão ___ gavetas.",
      "answer": "nas",
      "options": [
        "em as",
        "nas"
      ],
      "feedback": "Use 'nas' because 'em' combines with the plural 'as'."
    }
  ]
}

{
