  "title": "“since” e “for”",
  "rule": "Use “since” para indicar quando algo começou e “for” para indicar por quanto tempo dura. Em português, “desde” pode ajudar a lembrar o momento de início, enquanto “por” indica uma duração.",
  "contrast": [
    {
      "label": "“since” + momento de início",
      "example": "since 2015"
    },
    {
      "label": "“for” + duração",
      "example": "for ten years"
    }
  ],
  "drill": [
    {
      "sentence": "I've lived in this apartment ___ 2021.",
      "answer": "since",
      "options": [
        "since",
        "for"
      ],
      "feedback": "Use “since” porque 2021 indica quando a moradia começou."
    },
    {
      "sentence": "We have been friends ___ eight years.",
      "answer": "for",
      "options": [
        "since",
        "for"
      ],
      "feedback": "Use “for” porque oito anos indicam a duração da amizade."
    },
    {
      "sentence": "Maya has worked at the library ___ March.",
      "answer": "since",
      "options": [
        "for",
        "since"
      ],
      "feedback": "Use “since” porque março indica quando o trabalho começou."
    },
    {
      "sentence": "He's had that bike ___ six months.",
      "answer": "for",
      "options": [
        "since",
        "for"
      ],
      "feedback": "Use “for” porque seis meses indicam por quanto tempo ele tem a bicicleta."
    },
    {
      "sentence": "They have known each other ___ they were in college.",
      "answer": "since",
      "options": [
        "for",
        "since"
      ],
      "feedback": "Use “since” porque o período da faculdade indica quando eles começaram a se conhecer."
    }
  ]
}

